<script setup lang="ts">import{reactive,ref,onMounted,onUnmounted}from'vue';import{api,errorMessage}from'../api';import PageHeader from'../components/PageHeader.vue';import Modal from'../components/Modal.vue';import DataTable from'../components/DataTable.vue';import StatusBadge from'../components/StatusBadge.vue';import{Plus}from'lucide-vue-next';const rows=ref<any[]>([]),open=ref(false),error=ref('');const form=reactive({name:'Roteamento NF-e',document_type:'nfe',operation:'retrieve_by_key',stepsText:'[{"plugin_key":"repository","priority":10},{"plugin_key":"generic-http-xml","priority":20},{"plugin_key":"portal-assisted","priority":100}]'});const cols=[{key:'name',label:'Política'},{key:'document_type',label:'Documento'},{key:'operation',label:'Operação'},{key:'steps',label:'Etapas'},{key:'enabled',label:'Ativa'}];async function load(){rows.value=(await api.get('/routing-policies')).data}async function save(){try{await api.post('/routing-policies',{name:form.name,document_type:form.document_type,operation:form.operation,steps:JSON.parse(form.stepsText),settings:{stop_when:'complete_valid_xml'}});open.value=false;await load()}catch(e){error.value=errorMessage(e)}}onMounted(()=>{load();window.addEventListener('tenant-changed',load)});onUnmounted(()=>window.removeEventListener('tenant-changed',load))
</script><template><PageHeader title="Políticas de roteamento" subtitle="Defina a ordem dinâmica de fontes por documento, operação, cliente e CNPJ"><button class="btn primary" @click="open=true"><Plus :size="16"/>Nova política</button></PageHeader><section class="panel"><DataTable :columns="cols" :rows="rows"><template #cell-steps="{value}">{{value.length}} etapas</template><template #cell-enabled="{value}"><StatusBadge :status="value?'active':'disabled'"/></template></DataTable></section><Modal :open="open" title="Nova política" wide @close="open=false"><form class="form-grid" @submit.prevent="save"><label>Nome<input v-model="form.name" required/></label><label>Documento<select v-model="form.document_type"><option>nfe</option><option>nfce</option><option>cte</option><option>mdfe</option><option>nfse</option></select></label><label>Operação<select v-model="form.operation"><option value="retrieve_by_key">Consulta por chave</option><option value="discover">Descoberta</option><option value="synchronize">Sincronização</option></select></label><label class="span-2">Etapas JSON<textarea v-model="form.stepsText" rows="9"></textarea></label><div v-if="error" class="alert danger span-2">{{error}}</div><div class="form-actions span-2"><button class="btn primary">Salvar política</button></div></form></Modal></template>
